import{_ as t,o as r,c as e,a2 as d}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"人人有路保障体系","description":"","frontmatter":{},"headers":[],"relativePath":"ja/08-人人有路保障体系.md","filePath":"ja/08-人人有路保障体系.md","lastUpdated":1789183869000}'),l={name:"ja/08-人人有路保障体系.md"};function o(i,a,h,n,s,p){return r(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="人人有路保障体系" tabindex="-1">人人有路保障体系 <a class="header-anchor" href="#人人有路保障体系" aria-label="Permalink to &quot;人人有路保障体系&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>08</td></tr><tr><td>モジュール</td><td>総綱と核心設定</td></tr><tr><td>キーワード</td><td>人人有路、保障体系、進化の最低ライン、脆弱層、普遍的</td></tr></tbody></table><h2 id="第一節-人人有路の基本定義" tabindex="-1">第一節 人人有路の基本定義 <a class="header-anchor" href="#第一節-人人有路の基本定義" aria-label="Permalink to &quot;第一節 人人有路の基本定義&quot;">​</a></h2><p>人人有路は錨点共生文明の核心的な社会目標の一つであり、衡元宙におけるすべての生命が、その種族、出自、才能、レベル、富の状況にかかわらず、自分に適した進化の道を得ることができ、自分の努力を通じてレベルの向上と生命の完成を達成する機会を得ることができることを保証することを意味する。「道がある」とは、単に修練の法門を学べることだけでなく、使える資源があること、聞ける導師がいること、修練できる環境があること、依拠できる制度があることも指す。</p><p>人人有路と多労多得は、共生文明の分配制度の二つの柱である。多労多得が解決するのは「効率」の問題であり、強者がより多くの価値を創造するよう奨励する；人人有路が解決するのは「公平」の問題であり、弱者が進化システムに見捨てられないことを保証する。両者は相互に補完し合い、一方だけでは完全ではない。人人有路がなければ、多労多得は弱肉強食に退化する；多労多得がなければ、人人有路は平均主義に退化する。</p><h2 id="第二節-人人有路の必要性" tabindex="-1">第二節 人人有路の必要性 <a class="header-anchor" href="#第二節-人人有路の必要性" aria-label="Permalink to &quot;第二節 人人有路の必要性&quot;">​</a></h2><p>人人有路保障体系の確立は、以下の深い認識に基づいている：</p><h3 id="_2-1-進化権は最も基本的な生存権である" tabindex="-1">2.1 進化権は最も基本的な生存権である <a class="header-anchor" href="#_2-1-進化権は最も基本的な生存権である" aria-label="Permalink to &quot;2.1 進化権は最も基本的な生存権である&quot;">​</a></h3><p>修練文明において、進化権は単なる発展権であるだけでなく、生存権でもある。低レベルの生命は、宇宙の様々な危険（位面の変動、エネルギー嵐、異族の侵入など）に直面したとき、その生存確率は高レベルの生命よりもはるかに低い。したがって、すべての生命に進化の道があることを保証することは、本質的にすべての生命の基本的な生存権を保証することである。</p><h3 id="_2-2-初期才能の差異が進化の運命を決定すべきではない" tabindex="-1">2.2 初期才能の差異が進化の運命を決定すべきではない <a class="header-anchor" href="#_2-2-初期才能の差異が進化の運命を決定すべきではない" aria-label="Permalink to &quot;2.2 初期才能の差異が進化の運命を決定すべきではない&quot;">​</a></h3><p>各生命の初期才能（種族的才能、家庭背景、出生位面、先天的素質など）には大きな差異がある。略奪主義の時代には、この差異はしばしば乗り越えられない溝に拡大された——出自の良い生命は良質な資源を独占し、出自の悪い生命は基本的な修練法門すら得られなかった。共生文明は、初期才能の差異は客観的に存在するが、進化の運命を決定する唯一の要因であるべきではないと信じている。制度の役割は、この初期の差異を補い、すべての生命に後天的な努力を通じて運命を変える機会を与えることである。</p><h3 id="_2-3-見捨てられた個人は文明の潜在的な損失である" tabindex="-1">2.3 見捨てられた個人は文明の潜在的な損失である <a class="header-anchor" href="#_2-3-見捨てられた個人は文明の潜在的な損失である" aria-label="Permalink to &quot;2.3 見捨てられた個人は文明の潜在的な損失である&quot;">​</a></h3><p>すべての生命には進化の潜在能力があり、多くの場合、適切な道と資源が不足しているだけである。底辺で苦闘している生命は、適切な修練システムを得た後、驚くべき才能を示すかもしれない；「役立たず」と見なされている個人は、単に自分に適した進化の方向を見つけていないだけかもしれない。人人有路保障体系の意義は、潜在的な進化者を一人も見捨てず、文明の人材プールを可能な限り拡大することである。</p><h3 id="_2-4-普遍的進化は宇宙の昇維の基礎である" tabindex="-1">2.4 普遍的進化は宇宙の昇維の基礎である <a class="header-anchor" href="#_2-4-普遍的進化は宇宙の昇維の基礎である" aria-label="Permalink to &quot;2.4 普遍的進化は宇宙の昇維の基礎である&quot;">​</a></h3><p>宇宙全体の昇維は、少数の至高の強者だけに依存することはできず、万族の衆生の普遍的進化が必要である。錨点ネットワークの効率は、ネットワークに接続された生命の数と質に正の相関がある。より多くの生命が修練システムに接続し、レベルを向上させると、錨点ネットワーク全体のエネルギー循環と法則の運行がより安定し効率的になり、宇宙の昇維のプロセスもより速くなる。</p><h2 id="第三節-保障体系の階層構造" tabindex="-1">第三節 保障体系の階層構造 <a class="header-anchor" href="#第三節-保障体系の階層構造" aria-label="Permalink to &quot;第三節 保障体系の階層構造&quot;">​</a></h2><p>人人有路保障体系は四つのレベルに分かれており、基礎から進階までの完全な保障チェーンを形成している：</p><table tabindex="0"><thead><tr><th>レベル</th><th>名称</th><th>保障内容</th><th>カバー範囲</th></tr></thead><tbody><tr><td>第一レベル</td><td>基礎保障</td><td>無料の修練法門、最低限の資源配給、基礎医療教育</td><td>すべての生命、敷居なし</td></tr><tr><td>第二レベル</td><td>定向扶持</td><td>脆弱層への追加資源、導師、技術支援</td><td>初期才能の劣る個人と種族</td></tr><tr><td>第三レベル</td><td>機会拓展</td><td>進階修練の機会、位面間交流、特別プロジェクト参加権</td><td>潜在能力はあるが資源不足の修練者</td></tr><tr><td>第四レベル</td><td>成就激励</td><td>高レベル資源、錨点高級接続、文明栄誉</td><td>傑出した貢献をした修練者</td></tr></tbody></table><p>第一レベルは「最低ライン」であり、誰も見捨てられないことを保証する；第二レベルは「差異補填」であり、初期才能の差異を補う；第三レベルは「英才育成」であり、潜在能力のある個人により多くの機会を与える；第四レベルは「激励」であり、傑出した貢献者を報奨する。四つのレベルは段階的に進み、完全な保障と激励の体系を構成する。</p><h2 id="第四節-基礎保障の具体的内容" tabindex="-1">第四節 基礎保障の具体的内容 <a class="header-anchor" href="#第四節-基礎保障の具体的内容" aria-label="Permalink to &quot;第四節 基礎保障の具体的内容&quot;">​</a></h2><p>基礎保障は人人有路体系の核心であり、具体的に以下の内容を含む：</p><h3 id="_4-1-修練法門保障" tabindex="-1">4.1 修練法門保障 <a class="header-anchor" href="#_4-1-修練法門保障" aria-label="Permalink to &quot;4.1 修練法門保障&quot;">​</a></h3><p>三百套本源修練体系の基礎法門はすべての生命に無料で開放されており、いかなる敷居もない。各生命は自由に自分に適した修練体系を選ぶことができ、費用を支払う必要もなく、特定の宗派に加入する必要もなく、資格審査を受ける必要もない。錨点ネットワークは体系適合性評価を提供し、修練者が自分に最も適した道を見つけるのを助ける。</p><h3 id="_4-2-修練資源保障" tabindex="-1">4.2 修練資源保障 <a class="header-anchor" href="#_4-2-修練資源保障" aria-label="Permalink to &quot;4.2 修練資源保障&quot;">​</a></h3><p>聯産承包メカニズムと公共資源配給を通じて、各生命が基礎修練を維持するために必要な資源を得られることを保証する。基礎資源配給には、最低限のエネルギー供給、基礎修練丹薬、通用修練器材使用権が含まれる。資源不足の位面に対しては、錨点ネットワークを通じて位面間資源調配を行う。</p><h3 id="_4-3-修練環境保障" tabindex="-1">4.3 修練環境保障 <a class="header-anchor" href="#_4-3-修練環境保障" aria-label="Permalink to &quot;4.3 修練環境保障&quot;">​</a></h3><p>共生文明は各惑星と位面に公共修練場所を建設しており、公共修練室、エネルギー濃度調節区、法則感悟室などが含まれる。これらの場所はすべての生命に無料または低価格で開放されており、最も貧しい修練者にも適切な修練環境があることを保証する。</p><h3 id="_4-4-導師指導保障" tabindex="-1">4.4 導師指導保障 <a class="header-anchor" href="#_4-4-導師指導保障" aria-label="Permalink to &quot;4.4 導師指導保障&quot;">​</a></h3><p>異種族間導師ネットワークを構築し、高級修練者は初級修練者に基礎指導を提供する義務がある。各初級修練者は錨点ネットワークを通じて導師マッチングを申請し、無料で基礎的な質問応答と修練アドバイスを得ることができる。特別な困難を抱える修練者に対しては、一対一の定向指導を提供する。</p><h3 id="_4-5-医療リハビリ保障" tabindex="-1">4.5 医療リハビリ保障 <a class="header-anchor" href="#_4-5-医療リハビリ保障" aria-label="Permalink to &quot;4.5 医療リハビリ保障&quot;">​</a></h3><p>共生医療体系は修練者に無料の基礎医療と修練偏差リハビリサービスを提供する。修練の過程で負傷、修練偏差、エネルギー紊乱などの状況が発生した場合、タイムリーな治療とリハビリ支援を得ることができ、修練者が事故によって進化能力を失わないことを保証する。</p><h2 id="第五節-定向扶持の対象と方式" tabindex="-1">第五節 定向扶持の対象と方式 <a class="header-anchor" href="#第五節-定向扶持の対象と方式" aria-label="Permalink to &quot;第五節 定向扶持の対象と方式&quot;">​</a></h2><p>定向扶持は以下の脆弱層を対象とする：</p><ul><li><strong>低素質個人</strong>: 先天的素質が劣り、修練の進捗が遅い個人で、追加の資源配給とパーソナライズされた指導を受ける</li><li><strong>貧困種族</strong>: 全体的に資源が不足し、進化レベルが低い種族で、種族発展基金からの定向支援を受ける</li><li><strong>災後群体</strong>: 位面災害、戦争などの原因で家と資源を失った群体で、緊急救助と再建支援を受ける</li><li><strong>障害修練者</strong>: 様々な原因で身体または精神に障害を持つ修練者で、特別な修練補助器材とカスタマイズされた修練計画を受ける</li><li><strong>奇異生命</strong>: 通常の修練体系に適合しない奇異生命で、特別な評価とカスタマイズされた進化の道を受ける</li></ul><p>定向扶持の方式には、追加の資源配給、一対一の導師指導、カスタマイズされた修練計画、特別な器材提供、位面間交流の機会などが含まれる。扶持の目標は、脆弱層を基礎進化レベルに到達させるのを助け、その後徐々に正常な多労多得分配体系に移行させることである。</p><h2 id="第六節-保障体系の資金と資源の出所" tabindex="-1">第六節 保障体系の資金と資源の出所 <a class="header-anchor" href="#第六節-保障体系の資金と資源の出所" aria-label="Permalink to &quot;第六節 保障体系の資金と資源の出所&quot;">​</a></h2><p>人人有路保障体系の運営には大量の資源と資金が必要であり、その出所には以下が含まれる：</p><ol><li><strong>公共資源収入</strong>: 共生文明が直接管理する公共霊脈、エネルギー鉱脈、薬田などの資源の生産</li><li><strong>貢献調節税</strong>: 高貢献者から一定の割合の「貢献調節税」を徴収し、保障体系の運営に使用する（税率は累進的で、最高30%を超えない）</li><li><strong>文明発展基金</strong>: 錨点ネットワークの運営によって生まれた余剰エネルギーの一部が文明発展基金に注入される</li><li><strong>技術授権収入</strong>: 共生文明が所有する法則工学技術の授権使用料</li><li><strong>寄付と遺贈</strong>: 個人と種族の自発的な寄付</li></ol><p>保障体系の収支は万族共和議会の傘下にある保障委員会が管理し、定期的にすべての生命に帳簿を公開し、監督を受ける。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>人人有路保障体系は錨点共生文明の社会公平の礎石である。それは、修練と進化を核心とする文明において、いかなる生命も出自、才能、貧困によって進化システムに見捨てられないことを保証する。人人有路は平均主義を行うことではなく、各生命に公平な起点、上昇へのチャネル、見捨てられないという約束を与えることである。人人有路の保障の下で、各生命は自分自身の進化の道を見つけることができる。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (多労多得分配原理)</li><li>07-自生自长进化法则 (自生自長進化法則)</li><li>38-共生医疗体系 (共生医療体系)</li></ul>',43)])])}const b=t(l,[["render",o]]);export{_ as __pageData,b as default};
